import{_ as a,o as t,c as n,a5 as r}from"./chunks/framework.pJebtgMf.js";const m=JSON.parse('{"title":"AI 动态 · 2026-08-28","description":"","frontmatter":{"title":"AI 动态 · 2026-08-28","date":"2026-08-28T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-08/ai-news-2026-08-28.md","filePath":"news/2026-08/ai-news-2026-08-28.md","lastUpdated":null}'),s={name:"news/2026-08/ai-news-2026-08-28.md"};function i(o,e,c,l,p,h){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-动态-·-2026-08-28" tabindex="-1">AI 动态 · 2026-08-28 <a class="header-anchor" href="#ai-动态-·-2026-08-28" aria-label="Permalink to &quot;AI 动态 · 2026-08-28&quot;">​</a></h1><blockquote><p>截至 2026-08-28。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="anthropic-首次胜诉-法院裁定五角大楼将其列入供应链风险清单违法" tabindex="-1">Anthropic 首次胜诉：法院裁定五角大楼将其列入供应链风险清单违法 <a class="header-anchor" href="#anthropic-首次胜诉-法院裁定五角大楼将其列入供应链风险清单违法" aria-label="Permalink to &quot;Anthropic 首次胜诉：法院裁定五角大楼将其列入供应链风险清单违法&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-28">2026-08-28</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/763af1c8ae68.jpg" alt="配图"></p><p>联邦法官裁定特朗普政府将 Anthropic 列为国家安全供应链风险的行为违法，称其“非法且毫无根据”，并指出这是违反第一修正案的“非法报复”。Anthropic 此前因设定军事 AI 使用红线而遭此待遇，此次胜诉为其第二起针对五角大楼的诉讼增添了筹码。对读者：关注 AI 公司与政府监管的博弈，可能影响未来 AI 军事应用的合规边界。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/28/anthropic-gets-its-first-court-win-over-the-pentagons-supply-chain-risk-label/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="meta-高管跳槽-openai-负责东南亚及澳大利亚业务" tabindex="-1">Meta 高管跳槽 OpenAI，负责东南亚及澳大利亚业务 <a class="header-anchor" href="#meta-高管跳槽-openai-负责东南亚及澳大利亚业务" aria-label="Permalink to &quot;Meta 高管跳槽 OpenAI，负责东南亚及澳大利亚业务&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-28">2026-08-28</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/3f3ee8b6e290.jpg" alt="配图"></p><p>Meta 印度负责人 Sandhya Devanathan 离职加入 OpenAI，将负责东南亚和澳大利亚的部分运营。此举正值 Meta 在印度面临日益增长的审查之际，人才流动反映出 AI 领域竞争的加剧。对读者：关注头部 AI 公司的人才争夺，可能影响区域市场格局。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/28/meta-executive-leaves-for-openai-as-the-social-media-giant-faces-growing-scrutiny-in-india/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="openai、anthropic、谷歌等百余家公司联合呼吁防御-流氓-ai" tabindex="-1">OpenAI、Anthropic、谷歌等百余家公司联合呼吁防御“流氓 AI” <a class="header-anchor" href="#openai、anthropic、谷歌等百余家公司联合呼吁防御-流氓-ai" aria-label="Permalink to &quot;OpenAI、Anthropic、谷歌等百余家公司联合呼吁防御“流氓 AI”&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-28">2026-08-28</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/1a592d7f43b6.jpg" alt="配图"></p><p>OpenAI、Anthropic、谷歌等 100 多家科技公司联合发声，批评当前网络安全状况，并推广一种新解决方案，以抵御新一代网络威胁。此举表明 AI 行业正试图在安全问题上形成统一战线，共同应对潜在风险。对读者：关注 AI 安全联盟的后续动作，可能催生新的安全标准和工具。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/27/openai-anthropic-google-and-100-other-companies-call-for-action-to-defend-against-rogue-ai/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="传英伟达拟-130-亿美元收购-ai-模型库-hugging-face" tabindex="-1">传英伟达拟 130 亿美元收购 AI 模型库 Hugging Face <a class="header-anchor" href="#传英伟达拟-130-亿美元收购-ai-模型库-hugging-face" aria-label="Permalink to &quot;传英伟达拟 130 亿美元收购 AI 模型库 Hugging Face&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Ars Technica AI</span><time datetime="2026-08-28">2026-08-28</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/41842e5b37bb.jpg" alt="配图"></p><p>据 Ars Technica 报道，英伟达计划以 130 亿美元收购 AI 模型仓库 Hugging Face，此举将加强其在开源模型生态中的基础设施地位。随着开源模型兴趣增长，Hugging Face 作为关键平台价值凸显。对读者：若收购成行，可能影响开源模型分发格局，开发者需关注平台政策变化。</p><p class="news-entry-source"><a href="https://arstechnica.com/ai/2026/08/report-nvidia-to-acquire-ai-model-repository-hugging-face-for-13-billion/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="谷歌-gemini-notebook-新增-专家智能-功能-可交互图书内容" tabindex="-1">谷歌 Gemini Notebook 新增“专家智能”功能，可交互图书内容 <a class="header-anchor" href="#谷歌-gemini-notebook-新增-专家智能-功能-可交互图书内容" aria-label="Permalink to &quot;谷歌 Gemini Notebook 新增“专家智能”功能，可交互图书内容&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-08-28">2026-08-28</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/c99e6791bff7.png" alt="配图"></p><p>谷歌的 AI 笔记应用 Gemini Notebook 推出“Expert Intelligence”功能，允许用户从 Google Play 图书中导入书籍，并就内容提问、生成计划、信息图、AI 播客等。该功能在简报中展示了基于《食物规则》生成食谱等用例。对读者：适合利用该功能进行深度阅读和学习，提升知识管理效率。</p><p class="news-entry-source"><a href="https://www.theverge.com/tech/985567/google-gemini-notebook-expert-sources-books" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="meta-限制-ai-眼镜非自愿录制-降低隐私风险" tabindex="-1">Meta 限制 AI 眼镜非自愿录制，降低隐私风险 <a class="header-anchor" href="#meta-限制-ai-眼镜非自愿录制-降低隐私风险" aria-label="Permalink to &quot;Meta 限制 AI 眼镜非自愿录制，降低隐私风险&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Ars Technica AI</span><time datetime="2026-08-28">2026-08-28</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/49a46bebf784.jpg" alt="配图"></p><p>Meta 修复了 AI 眼镜，当用户遮挡安全指示灯时停止录制，以减少非自愿录制行为。此举回应了隐私担忧，使产品“不那么令人毛骨悚然”。对读者：使用 AI 眼镜时注意隐私保护，了解录制指示灯的作用。</p><p class="news-entry-source"><a href="https://arstechnica.com/tech-policy/2026/08/meta-tweaks-ai-glasses-to-block-some-creepy-recordings-but-privacy-risks-remain/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="gemini-omni-1-1-flash-发布-增强生成式视频控制能力" tabindex="-1">Gemini Omni 1.1 Flash 发布，增强生成式视频控制能力 <a class="header-anchor" href="#gemini-omni-1-1-flash-发布-增强生成式视频控制能力" aria-label="Permalink to &quot;Gemini Omni 1.1 Flash 发布，增强生成式视频控制能力&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Google DeepMind</span><time datetime="2026-08-28">2026-08-28</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/bd7d202db54a.png" alt="配图"></p><p>谷歌 DeepMind 发布 Gemini Omni 1.1 Flash，为开发者带来新的创意控制和生成式视频能力。该模型旨在提供更精细的控制，适用于构建多模态应用。对读者：开发者可探索新 API 以增强应用的视频生成和交互体验。</p><p class="news-entry-source"><a href="https://deepmind.google/blog/gemini-omni-1-1-flash-lets-you-build-with-more-control/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="智谱开源-glm-5-3-flash-原生多模态模型" tabindex="-1">智谱开源 GLM-5.3-Flash 原生多模态模型 <a class="header-anchor" href="#智谱开源-glm-5-3-flash-原生多模态模型" aria-label="Permalink to &quot;智谱开源 GLM-5.3-Flash 原生多模态模型&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">少数派</span><time datetime="2026-08-28">2026-08-28</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/03571149d61b.png" alt="配图"></p><p>智谱发布并开源 GLM-5.3-Flash，这是 GLM-5 系列首款原生多模态模型，采用 MoE 架构，总参数 320B，激活 18B，支持文本和图像输入及 100 万上下文，以 MIT 许可证开放。评测得分与 Claude Opus 4.8 持平。对读者：可免费用于多模态应用开发，但需注意硬件要求。</p><p class="news-entry-source"><a href="https://sspai.com/post/113922" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="谷歌发布-gemini-3-5-transcribe-语音转文本模型" tabindex="-1">谷歌发布 Gemini 3.5 Transcribe 语音转文本模型 <a class="header-anchor" href="#谷歌发布-gemini-3-5-transcribe-语音转文本模型" aria-label="Permalink to &quot;谷歌发布 Gemini 3.5 Transcribe 语音转文本模型&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-08-28">2026-08-28</time></p><p>谷歌推出 Gemini 3.5 Transcribe，一个语音转文本模型，在 85 种以上语言中平均词错误率（WER）为 2.6%。该模型旨在提供高精度的转录服务。对读者：可用于多语言语音识别场景，提升转录效率。</p><p class="news-entry-source"><a href="https://news.google.?oc=5" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="anthropic-发布新硬件标准-让-ai-智能体控制物理世界" tabindex="-1">Anthropic 发布新硬件标准，让 AI 智能体控制物理世界 <a class="header-anchor" href="#anthropic-发布新硬件标准-让-ai-智能体控制物理世界" aria-label="Permalink to &quot;Anthropic 发布新硬件标准，让 AI 智能体控制物理世界&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Ars Technica AI</span><time datetime="2026-08-28">2026-08-28</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/3fa3b6dc5bfd.png" alt="配图"></p><p>Anthropic 推出标准化驱动接口，旨在让设备与 AI 及彼此通信，使 AI 智能体能够控制物理设备。该标准有望推动智能体在物联网和自动化领域的应用。对读者：关注该标准，可能影响未来智能硬件开发。</p><p class="news-entry-source"><a href="https://arstechnica.com/ai/2026/08/anthropics-new-hardware-standard-lets-ai-agents-control-the-physical-world/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="cloudflare-发布-kitesurf-面向-ai-智能体的轻量浏览器引擎" tabindex="-1">Cloudflare 发布 Kitesurf：面向 AI 智能体的轻量浏览器引擎 <a class="header-anchor" href="#cloudflare-发布-kitesurf-面向-ai-智能体的轻量浏览器引擎" aria-label="Permalink to &quot;Cloudflare 发布 Kitesurf：面向 AI 智能体的轻量浏览器引擎&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-28">2026-08-28</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/94a5555a8ee1.jpg" alt="配图"></p><p>Cloudflare 推出 Kitesurf，一款专为自动化任务设计的轻量级浏览器，支持 Playwright 和 Puppeteer 驱动，资源消耗低于完整 Chromium。它在 WebAssembly/Rust 环境中运行，提供独立 JavaScript 环境和 DOM。对读者：适合用于 AI 智能体的网页抓取和自动化测试，降低资源开销。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/JDYKJmiY9vTRSw47t15a?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><p>（本日无新条目）</p></div>',8)])])}const g=a(s,[["render",i]]);export{m as __pageData,g as default};
